// ============================================================
// trtcClient.js — TRTC Web SDK wrapper
// Tencent Cloud TRTC: no Chinese ID needed, global TURN relay works in China
// ============================================================
import TRTC from 'trtc-js-sdk';

// Config (hardcoded for now — user supplied credentials)
// SDKAppID: 100048996157
const SDK_APP_ID = 100048996157;

// Server endpoint for UserSig generation (keeps SecretKey server-side)
const USERSIG_SERVER = 'http://localhost:3002';

// Singleton TRTC instance
let trtcClient = null;
let localStream = null;
let isJoined = false;

// ============================================================
// Fetch UserSig from server
// ============================================================
export async function getUserSig(userId) {
  try {
    const res = await fetch(`${USERSIG_SERVER}/usersig?userId=${encodeURIComponent(userId)}`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    return data.userSig;
  } catch (err) {
    console.error('[TRTC] Failed to get UserSig:', err.message);
    throw new Error('Cannot reach UserSig server. Make sure the signaling server is running (npm run server).');
  }
}

// ============================================================
// Init TRTC client
// ============================================================
function createClient(userId, userSig) {
  trtcClient = TRTC.createClient({
    sdkAppId: SDK_APP_ID,
    userId,
    userSig,
  });
  return trtcClient;
}

// ============================================================
// Join a TRTC room
// ============================================================
export async function joinRoom({ roomId, userId, userName }, callbacks) {
  // Fetch UserSig first
  let userSig;
  try {
    userSig = await getUserSig(userId);
  } catch (err) {
    callbacks?.onError?.('Cannot reach UserSig server. Please start the signaling server: npm run server');
    return;
  }

  const client = createClient(userId, userSig);
  window.__trtcUserId = userId;
  window.__trtcUserName = userName;

  // ---- Local stream ----
  try {
    localStream = TRTC.createStream({
      userId,
      audio: true,
      video: true,
    });
    await localStream.initialize();
    console.log('[TRTC] Local stream initialized');
  } catch (err) {
    console.warn('[TRTC] Camera error, trying audio-only:', err.message);
    try {
      localStream = TRTC.createStream({ userId, audio: true, video: false });
      await localStream.initialize();
    } catch (err2) {
      callbacks?.onError?.('Camera/microphone access denied. Please allow permissions.');
      return;
    }
  }

  // ---- Set up event listeners ----
  client.on(TRTC.EVENT.REMOTE_USER_JOIN, ({ userId: uid }) => {
    console.log('[TRTC] Remote user joined:', uid);
    callbacks?.onPeerJoined?.(uid, uid);
  });

  client.on(TRTC.EVENT.REMOTE_USER_LEAVE, ({ userId: uid }) => {
    console.log('[TRTC] Remote user left:', uid);
    callbacks?.onPeerLeft?.(uid);
  });

  client.on(TRTC.EVENT.REMOTE_STREAM_ADDED, ({ stream }) => {
    const uid = stream.getUserId();
    console.log('[TRTC] Remote stream added:', uid);
    // Subscribe to the remote stream
    client.subscribe(stream, { audio: true, video: true })
      .then(() => {
        console.log('[TRTC] Subscribed to remote stream:', uid);
        callbacks?.onRemoteStream?.(uid, stream);
      })
      .catch(err => console.error('[TRTC] Subscribe failed:', err));
  });

  client.on(TRTC.EVENT.REMOTE_STREAM_REMOVED, ({ stream }) => {
    console.log('[TRTC] Remote stream removed:', stream.getUserId());
  });

  client.on(TRTC.EVENT.REMOTE_STREAM_SUBSCRIBED, ({ stream }) => {
    const uid = stream.getUserId();
    console.log('[TRTC] Remote stream subscribed:', uid);
    callbacks?.onRemoteStream?.(uid, stream);
  });

  client.on(TRTC.EVENT.RTC_ERROR, ({ message }) => {
    console.error('[TRTC] Error:', message);
  });

  client.on(TRTC.EVENT.KICKED_OUT, () => {
    callbacks?.onError?.('You were removed from the room (duplicate login).');
  });

  // ---- Join room ----
  try {
    // TRTC roomId must be a number < 2^32, so hash string to number
    const numericRoomId = hashRoomId(String(roomId));
    await client.join({ roomId: numericRoomId });
    console.log('[TRTC] Joined room:', roomId, '(numeric:', numericRoomId + ')');
    isJoined = true;

    // Publish local stream
    await client.publish(localStream);
    console.log('[TRTC] Local stream published');

    callbacks?.onJoined?.({ roomId, userId });
  } catch (err) {
    console.error('[TRTC] Join failed:', err);
    // Provide helpful error messages
    const msg = err.message || String(err);
    if (msg.includes('6026') || msg.includes('wrong userSig')) {
      callbacks?.onError?.('UserSig invalid. Please restart the signaling server and try again.');
    } else if (msg.includes('6003') || msg.includes('room id')) {
      callbacks?.onError?.(`Room "${roomId}" not found or access denied.`);
    } else {
      callbacks?.onError?.('Failed to join room: ' + msg);
    }
    return;
  }
}

// Hash a string room ID to a number for TRTC
function hashRoomId(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return Math.abs(hash) % 4294967295;
}

// ============================================================
// Leave room
// ============================================================
export async function leaveRoom() {
  if (localStream) {
    try { localStream.stop(); } catch (e) {}
    try { localStream.close(); } catch (e) {}
    localStream = null;
  }

  if (trtcClient) {
    try { await trtcClient.leave(); } catch (e) {}
    trtcClient = null;
    isJoined = false;
  }
}

// ============================================================
// Toggle mic
// ============================================================
export function toggleMic() {
  if (!localStream) return false;
  const audioTrack = localStream.getAudioTrack();
  if (!audioTrack) return false;
  const enabled = !audioTrack.isAudioEnabled();
  audioTrack.setAudioEnabled(enabled);
  return enabled;
}

// ============================================================
// Toggle camera
// ============================================================
export function toggleCamera() {
  if (!localStream) return false;
  const videoTrack = localStream.getVideoTrack();
  if (!videoTrack) return false;
  const enabled = !videoTrack.isVideoEnabled();
  videoTrack.setVideoEnabled(enabled);
  return enabled;
}

// ============================================================
// Start screen share
// ============================================================
export async function startScreenShare() {
  if (!trtcClient || !localStream) return null;
  try {
    const screenStream = await TRTC.createStream({
      userId: window.__trtcUserId,
      audio: false,
      video: true,
      screen: true, // screen share mode
    });
    await screenStream.initialize();
    return screenStream;
  } catch (err) {
    console.warn('[TRTC] Screen share cancelled or failed:', err.message);
    return null;
  }
}

// ============================================================
// Get local stream (for preview / direct access)
// ============================================================
export function getLocalStream() {
  return localStream;
}

// ============================================================
// Check if joined
// ============================================================
export function isInRoom() {
  return isJoined;
}
